    "source_site": "Giallo Zafferano",
    "source_url": "https://ricette.giallozafferano.it/Pizza-bianca-romana.html",
    "prep_time_min": 30,
    "cook_time_min": 40,
    "total_time_min": 70,
    "servings": 4,
    "difficulty": "difficile",
